while (true)
{
    Console.Write("\n🔍 Research topic: ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.ClearNotes();

    Console.WriteLine($"\n📚 Researching: {topic}\n");

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 15,
        Tools = tools,
        ModelOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        },
    };

    await foreach (var message in agent.InvokeStreamingAsync(messages, options))
    {
        if (message.Role == ChatRole.Assistant)
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine();
}

Console.WriteLine("\nGoodbye!");

// --- Tools ---

static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information on a query.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Uses the DuckDuckGo instant-answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url, cancellationToken);
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract / main answer
            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                results.Add($"[Summary] {abstractText}");

            if (root.TryGetProperty("AbstractSource", out var src) && src.GetString() is { Length: > 0 } source)
                results.Add($"[Source] {source}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        results.Add($"- {t}");
                        count++;
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try a more specific search.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try rephrasing the query.";
        }
    }
}

sealed class Notepad
{
    private readonly List<(string Source, string Content)> _notes = [];

    [Description("Save a research note with a source label and content.")]
    public string AddNote(
        [Description("Source or label for this note")] string source,
        [Description("The note content")] string content)
    {
        _notes.Add((source, content));
        Console.WriteLine($"  📝 Note added: [{source}] ({content.Length} chars)");
        return $"Note #{_notes.Count} saved from '{source}'.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"Note #{i + 1} [{n.Source}]:\n{n.Content}"));
    }

    [Description("Clear all saved research notes.")]
    public string ClearNotes()
    {
        _notes.Clear();
        return "All notes cleared.";
    }
}

